#!/usr/bin/env node
/**
 * The phone app's copy of the agents' marks, cut from the desktop sprite in
 * src/daemon/brand-icons.ts (itself generated by gen-brand-icons.mjs). The app
 * is its own package and can't import the daemon's sources, so this writes
 * app/src/brand-marks.ts: one standalone <svg> per kind, for react-native-svg's
 * SvgXml. Run after regenerating the sprite:  node scripts/gen-app-brand-marks.mjs
 */
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const src = fs.readFileSync(path.join(root, "src/daemon/brand-icons.ts"), "utf8");
const marks = {};
for (const m of src.matchAll(/<symbol id="brand-([^"]+)" viewBox="([^"]+)">([\s\S]*?)<\/symbol>/g)) {
  const [, kind, viewBox, inner] = m;
  marks[kind] = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}">${inner}</svg>`;
}
const alias = Object.fromEntries([...src.matchAll(/"([^"]+)": "([^"]+)",?\n/g)].filter(([, k, v]) => marks[v] && !marks[k]).map(([, k, v]) => [k, v]));
const out = `/**
 * The agents' own marks, for the phone. GENERATED by
 * scripts/gen-app-brand-marks.mjs from src/daemon/brand-icons.ts (which comes
 * from @lobehub/icons, MIT). Don't hand-edit; regenerate. Each logo is the
 * trademark of its owner, used only to identify that agent.
 *
 * The mono marks (opencode, Grok) paint in currentColor: the caller sets it.
 */

export const BRAND_MARKS: Record<string, string> = ${JSON.stringify(marks, null, 2)};

/** Kinds that draw another kind's mark. */
export const BRAND_MARK_ALIAS: Record<string, string> = ${JSON.stringify(alias, null, 2)};

/** Marks with no colour of their own. */
export const MONO_MARKS = new Set(["opencode", "grok-code"]);
`;
fs.writeFileSync(path.join(root, "app/src/brand-marks.ts"), out);
console.log(`wrote app/src/brand-marks.ts: ${Object.keys(marks).join(", ")}; aliases ${JSON.stringify(alias)}`);
